    "summaryZh": "2026-07-24 百度热搜第 13 名，热度 676.0万。7月23日，四年一度的菲尔兹奖在美国费城揭晓，王虹、邓煜两位中国籍数学家获奖。世界著名数学家、清华大学求真书院院长丘成桐表示：我希望他们回国任教，这对我们中国很重要。我也希望我们求真书院优秀的年轻人以王虹、邓煜为榜样，期望未来这些中国本土训练的学者能够拿到菲尔兹奖。",
